window.KALU_LESSONS=[{"id":0,"cat":"Comece aqui","title":"Como usar esta aulona","idea":"Imagine uma viagem: o edital é o mapa; cada aula é uma parada; os exercícios são placas que mostram se você pegou o caminho.","explain":"Faça um slide por vez. Leia a explicação, tente prever o exemplo e responda à pergunta SEM olhar ajuda. Marque como estudado e anote sua dúvida. A resposta aparece somente quando você escolher uma alternativa. O histórico fica salvo no seu navegador.","example":"Rotina sugerida: 20 minutos de aula + 5 de descanso + 10 de questões. No fim, revise os erros.","question":"Qual forma mais ajuda a verificar aprendizagem?","why":"Recuperar a informação da memória e corrigir erros cria uma prática ativa.","law":""},{"id":3,"cat":"Comece aqui","title":"O desenho da prova de 2026","idea":"Pense em três caixas: Português, Direito e Conhecimentos Gerais. Cada uma tem um peso na sua preparação.","explain":"Serão 70 itens de múltipla escolha: 16 de Português, 30 de Direito e 24 de Conhecimentos Gerais (4 Atualidades/PcD, 4 Matemática, 9 Informática e 7 Raciocínio Lógico). Há também redação. Todas as objetivas valem o mesmo.","example":"30 das 70 questões são de Direito: mais de 4 em cada 10. Portanto, Direito tem prioridade quantitativa.","question":"Qual disciplina tem o maior número de questões em 2026?","why":"O edital de 2026 prevê 30 questões de Direito.","law":"Edital 02/2026, Anexo VIII"},{"id":6,"cat":"Comece aqui","title":"Como funciona a eliminação","idea":"É como passar por três portões: precisa ter nota total suficiente E não reprovar nas caixas eliminatórias.","explain":"Na objetiva: pelo menos 50% de Português (8/16), pelo menos 50% de Direito (15/30) e nota geral mínima 5/10 (35/70). Conhecimentos Gerais é classificatório. Além disso, a redação só é corrigida para os mais bem classificados no limite previsto por circunscrição.","example":"Você acerta 45 itens, mas apenas 7 de Português: NÃO fica habilitado, apesar da nota total.","question":"Com 40 acertos totais, 7 em Português e 20 em Direito, passa na objetiva?","why":"É necessário acertar ao menos 8/16 em Português.","law":"Edital 02/2026, Capítulos X e XI"},{"id":9,"cat":"Comece aqui","title":"O que a prova anterior ensina","idea":"A prova de 2025 é um retrovisor, não uma bola de cristal.","explain":"A prova de 07/12/2025 cobrou interpretação, gramática, crimes contra a administração pública, atos processuais, direitos fundamentais, normas internas, Excel/Word, lógica e atualidades. Isso mostra o estilo de aplicação da Vunesp. O edital novo é o filtro final.","example":"Quando uma prova antiga faz pergunta sobre um processo, procure a regra na lei e entenda como ela vira uma situação concreta.","question":"O que manda se a prova anterior e o edital atual divergirem?","why":"O edital vigente define o conteúdo e as regras.","law":"Prova Vunesp TJ-SP 07/12/2025; Edital 02/2026"},{"id":12,"cat":"Português","title":"Interpretação: o texto diz ou você imagina?","idea":"Um texto é uma fotografia: responda ao que aparece nela, não ao que gostaria que aparecesse.","explain":"Leia a pergunta antes do texto. Separe fatos expressos (estão escritos) e inferências (conclusões autorizadas pelas pistas). Em questões de Vunesp, desconfie de “sempre”, “nunca”, “somente” quando o texto diz algo mais moderado.","example":"Texto: “Alguns servidores trabalham remotamente.” É correto dizer que pelo menos alguns trabalham remotamente; não é correto dizer que todos trabalham assim.","question":"De “Muitos cidadãos usam o serviço digital”, conclui-se que:","why":"“Muitos” indica uma parcela, não a totalidade.","law":""},{"id":15,"cat":"Português","title":"Tema, tese e argumento","idea":"Tema é o assunto da conversa; tese é o que alguém defende; argumento é a razão usada.","explain":"Se o texto fala de trabalho remoto, esse é o tema. Se o autor diz “trabalho remoto melhora a produtividade”, essa é a tese. Um dado de redução de tempo de transporte usado para justificar a ideia é um argumento.","example":"Tema: transporte urbano. Tese: ônibus mais frequentes reduzem espera. Argumento: intervalos menores entre viagens.","question":"Qual trecho é uma tese?","why":"A tese sustenta uma posição que pode ser defendida.","law":""},{"id":18,"cat":"Português","title":"Conectivos: as pontes do pensamento","idea":"Conectivos são plaquinhas na estrada: “mas” faz curva; “porque” explica motivo.","explain":"Causa: porque, visto que. Consequência: portanto, por isso. Oposição: porém, contudo. Concessão: embora, ainda que. Condição: se, caso. Finalidade: para que. Essas relações aparecem tanto em interpretação quanto em gramática.","example":"“Embora chovesse, compareceu”: algo poderia dificultar a ida, mas não impediu.","question":"“Embora estivesse cansada, estudou.” Expressa:","why":"Há uma dificuldade admitida, sem impedir a ação.","law":""},{"id":21,"cat":"Português","title":"Coesão: quem é “ele”?","idea":"Coesão é o barbante que prende frases e referências.","explain":"Pronomes e expressões substituem ideias anteriores: “Maria entregou o documento. Ela o assinou.” Ela = Maria; o = documento. Às vezes, “isso” retoma uma oração inteira. Volte ao trecho anterior e confira a concordância e o sentido.","example":"“O processo foi suspenso. Isso surpreendeu a equipe.” “Isso” retoma o fato de a suspensão ocorrer.","question":"Em “Ana revisou o texto e o enviou”, “o” retoma:","why":"O pronome substitui “texto”.","law":""},{"id":24,"cat":"Português","title":"Sentido literal e figurado","idea":"Palavra literal veste roupa comum; figurada usa fantasia para comunicar outra ideia.","explain":"“A porta fechou” é literal. “A decisão abriu portas” é figurado: criou oportunidades. A banca pode cobrar sentido contextual, sinônimos e antônimos; substitua a palavra mentalmente na frase completa.","example":"“Um parecer enxuto” normalmente significa um parecer conciso, não magro.","question":"“Explicação concisa” é uma explicação:","why":"Conciso significa breve, objetivo.","law":""},{"id":27,"cat":"Português","title":"Concordância: quem combina com quem?","idea":"Sujeito e verbo dançam em dupla: singular com singular, plural com plural.","explain":"O verbo “existir” concorda: “Existem dúvidas”. “Haver” no sentido de existir é impessoal: “Há dúvidas” (não “haviam dúvidas”). “Fazer” indicando tempo transcorrido também fica no singular: “Faz três anos”.","example":"“Devem existir recursos”, mas “Deve haver recursos”.","question":"Qual está correta?","why":"“Existem” concorda com “processos”; as demais usam impessoais indevidamente.","law":""},{"id":30,"cat":"Português","title":"Crase sem desespero","idea":"Crase é a união de dois “a”: preposição + artigo feminino.","explain":"Teste simples: troque a palavra feminina por masculina. Se “à” virar “ao”, há boa indicação de crase. “Fui à secretaria” → “Fui ao cartório”. Antes de verbo, em regra, não ocorre crase: “Começou a estudar”.","example":"“Entregou a documentação à diretora.” = entregou ao diretor.","question":"Qual frase exige crase?","why":"Chegar a + a audiência = à audiência.","law":""},{"id":33,"cat":"Português","title":"Pontuação: a vírgula muda o sentido","idea":"Vírgula não é pausa de respiração; ela organiza pedaços da oração.","explain":"Evite separar sujeito do verbo: “Os servidores do setor chegaram”. Use vírgulas para vocativo, enumerações e expressões deslocadas: “Na segunda-feira, o tribunal abriu”. Orações explicativas também podem vir isoladas.","example":"“Vamos comer, crianças” chama as crianças; “vamos comer crianças” sugere outra coisa.","question":"Qual tem vírgula bem empregada?","why":"A expressão adverbial antecipada pode ser separada por vírgula.","law":""},{"id":36,"cat":"Português","title":"Regência e pronomes","idea":"Alguns verbos “pedem” preposições, como uma chave pede determinada fechadura.","explain":"“Assistir ao filme” (ver); “obedecer à norma”; “preferir X a Y”. Colocação pronominal: palavras negativas atraem o pronome para antes do verbo: “Não me avisaram”. Observe sempre o sentido do verbo.","example":"“Não se deve divulgar o documento” tem pronome antes do verbo por causa de “não”.","question":"Qual está adequada?","why":"Obedecer exige a preposição “a”, somada ao artigo “a”.","law":""},{"id":39,"cat":"Direito","title":"O que é Direito? Um jogo com regras","idea":"Pense numa escola: existem regras, quem decide conflitos e quem faz cumprir decisões.","explain":"Direito Constitucional define as regras maiores do Estado; Administrativo explica como a administração atua; Penal identifica crimes e penas; Processual descreve o caminho do processo. Leis internas do TJ regulam rotinas da instituição.","example":"Se alguém comete um crime contra a Administração: Penal descreve o delito; Processo Penal cuida da apuração e julgamento.","question":"A regra sobre a forma de apresentar recurso pertence principalmente ao:","why":"Recurso é mecanismo do processo, logo tem natureza processual.","law":""},{"id":42,"cat":"Direito","title":"Constituição: o livro das regras maiores","idea":"É o “manual principal” que orienta as outras leis.","explain":"A Constituição trata de direitos fundamentais, organização do Estado, poderes e administração pública. O edital cobra partes determinadas: direitos e garantias individuais e coletivos, direitos sociais, nacionalidade, Administração Pública (arts. 37 a 41) e art. 92.","example":"Uma lei ordinária não pode contrariar o texto constitucional.","question":"A Constituição está:","why":"É o fundamento normativo superior para as demais normas.","law":""},{"id":45,"cat":"Direito","title":"LIMPE: os cinco cuidados da Administração","idea":"L-I-M-P-E é um lembrete: Legalidade, Impessoalidade, Moralidade, Publicidade, Eficiência.","explain":"Legalidade: servidor segue autorização legal. Impessoalidade: não favorece amigos. Moralidade: conduta ética. Publicidade: transparência, com exceções legais. Eficiência: serviço com qualidade e bom uso dos recursos.","example":"Servidor que escolhe um amigo para receber vantagem viola impessoalidade e pode atingir outros princípios.","question":"Ocultar um ato para impedir fiscalização atinge principalmente:","why":"O núcleo do problema é impedir transparência.","law":""},{"id":48,"cat":"Direito","title":"Direitos individuais e remédios constitucionais","idea":"Remédio constitucional é ferramenta de proteção de direitos.","explain":"Habeas corpus protege liberdade de locomoção contra ilegalidade ou abuso de poder; mandado de segurança protege direito líquido e certo, quando cabível; habeas data trata de acesso/retificação de dados pessoais nas hipóteses legais; ação popular permite a cidadão combater atos lesivos aos bens juridicamente protegidos.","example":"Prisão ilegal → pense em habeas corpus. Negativa ilegal de certidão/documento com direito comprovável → examine mandado de segurança.","question":"Qual instrumento se relaciona com liberdade de locomoção?","why":"O habeas corpus tutela a liberdade de locomoção.","law":""},{"id":51,"cat":"Direito","title":"Direitos sociais e nacionalidade","idea":"Direitos sociais cuidam de condições básicas; nacionalidade define vínculo jurídico com o Estado.","explain":"O art. 6º apresenta direitos sociais. Nacionalidade distingue brasileiros natos e naturalizados conforme regras constitucionais. A banca pode apresentar situação e pedir a classificação ou um direito previsto.","example":"Educação e saúde são exemplos de direitos sociais previstos constitucionalmente.","question":"Qual é exemplo de direito social?","why":"Educação integra o rol constitucional de direitos sociais.","law":""},{"id":54,"cat":"Direito","title":"Administração: cargo, emprego e função","idea":"Cargo público é um lugar definido em lei dentro de uma estrutura; emprego costuma seguir regime trabalhista.","explain":"Servidores efetivos, concurso público, direitos e deveres, acumulações e estabilidade aparecem em Constituição e Estatuto paulista. A estabilidade constitucional, como regra, pressupõe cargo efetivo, concurso, período de três anos de efetivo exercício e avaliação especial de desempenho.","example":"Passar em concurso e tomar posse não significa adquirir estabilidade no primeiro dia.","question":"Estabilidade de servidor efetivo surge automaticamente no dia da posse?","why":"Em regra há três anos de efetivo exercício e avaliação especial de desempenho.","law":""},{"id":57,"cat":"Direito","title":"Direito Penal: crime e processo não são sinônimos","idea":"Crime diz o que é proibido; processo diz como se investiga e julga.","explain":"Em Penal, decore menos nomes soltos e crie uma tabela: quem praticou? que conduta? houve intenção exigida? qual objeto protegido? Os artigos do edital focam falsidades e crimes contra a Administração/Justiça.","example":"Um servidor que desvia dinheiro de que tem posse em razão do cargo pode cometer peculato, dependendo dos elementos do tipo.","question":"A descrição do comportamento que constitui crime é estudada em:","why":"O tipo penal define a conduta proibida.","law":""},{"id":60,"cat":"Direito","title":"Peculato: a confiança quebrada","idea":"Imagine alguém encarregado de guardar o dinheiro da escola e que se apropria dele.","explain":"No peculato-apropriação, o funcionário público se apropria de dinheiro, valor ou outro bem móvel de que tem posse em razão do cargo. Há outras modalidades; leia o art. 312 do CP. A relação com o cargo e a posse são pistas importantes.","example":"Responsável pelo caixa da repartição toma para si valor sob sua guarda: pense em peculato.","question":"Qual sinal aponta para peculato-apropriação?","why":"O núcleo é apropriar-se de bem com posse em razão do cargo.","law":"Código Penal, art. 312"},{"id":63,"cat":"Direito","title":"Corrupção passiva x concussão","idea":"Duas palavras fazem diferença: SOLICITAR/RECEBER e EXIGIR.","explain":"Corrupção passiva (art. 317): solicitar, receber ou aceitar promessa de vantagem indevida em razão da função. Concussão (art. 316): exigir vantagem indevida, valendo-se da função. A banca costuma trocar o verbo para testar a distinção.","example":"Servidor: “Pague para eu agilizar” pode sugerir solicitação; “Você tem que pagar ou sofrerá consequência” aponta para exigência.","question":"“Exigir vantagem indevida em razão da função” remete a:","why":"O verbo nuclear de concussão é “exigir”.","law":"Código Penal, arts. 316–317"},{"id":66,"cat":"Direito","title":"Prevaricação: o interesse pessoal no atraso","idea":"É como alguém esconder uma tarefa pública por interesse particular.","explain":"Prevaricação (art. 319): retardar ou deixar de praticar indevidamente ato de ofício, ou praticá-lo contra disposição expressa de lei, para satisfazer interesse ou sentimento pessoal. O motivo pessoal específico é importante.","example":"Servidor deixa processo parado de propósito para favorecer pessoa próxima: pode configurar prevaricação se os elementos estiverem presentes.","question":"Qual detalhe é essencial no tipo de prevaricação?","why":"A finalidade especial é componente do tipo descrito no art. 319.","law":"Código Penal, art. 319"},{"id":69,"cat":"Direito","title":"Falsidade documental: verdade no papel","idea":"Documentos públicos dependem de confiança na autenticidade.","explain":"O edital inclui crimes contra a fé pública (CP arts. 293–305 e correlatos). Diferencie falsificar documento (alterar/produzir material falso) de falsidade ideológica (inserir declaração falsa em documento verdadeiro, nos termos da lei).","example":"Criar um documento público inteiramente falso é diferente de inserir informação falsa em um documento formalmente verdadeiro.","question":"Qual contraste é correto?","why":"A diferença de natureza da falsidade ajuda a identificar os tipos.","law":""},{"id":72,"cat":"Direito","title":"Processo Civil: a viagem de uma ação","idea":"Um processo é uma fila de etapas, não uma conversa sem regras.","explain":"Visão geral: petição inicial → análise judicial/citação → resposta do réu → prova/instrução quando cabível → decisão → eventuais recursos → cumprimento. O CPC traz muitas exceções e procedimentos específicos; use esta sequência como mapa inicial.","example":"Uma pessoa cobra valor judicialmente; o réu é citado para integrar o processo e poder responder.","question":"A citação, em termos gerais, serve para:","why":"Citação dá ciência e chama a integrar o processo.","law":"Código de Processo Civil, art. 238"},{"id":75,"cat":"Direito","title":"Intimação x citação","idea":"Citação chama para a história; intimação informa sobre um ato dentro dela.","explain":"No CPC, citação convoca réu, executado ou interessado a integrar a relação processual. Intimação dá ciência a alguém sobre atos e termos do processo. Leia os dispositivos vigentes previstos no edital e as formas eletrônicas.","example":"Primeira convocação de réu: geralmente citação. Comunicação de decisão ao advogado: intimação.","question":"Avisar uma parte sobre decisão já proferida é, em geral:","why":"O aviso de ato processual é intimação.","law":"CPC, arts. 238 e 269"},{"id":78,"cat":"Direito","title":"Prazos processuais: o relógio da Justiça","idea":"Um prazo é cronômetro com regras próprias.","explain":"No processo civil, como regra, prazos processuais em dias contam-se em dias úteis (art. 219 do CPC); existem hipóteses específicas e regras de início/suspensão. Processo penal tem disciplina diferente. Nunca transfira uma regra de um código para o outro.","example":"Um prazo de 5 dias úteis no CPC não significa simplesmente 5 dias corridos.","question":"No CPC, a contagem em dias dos prazos processuais considera, como regra:","why":"O art. 219 do CPC dispõe sobre contagem em dias úteis.","law":"CPC, art. 219"},{"id":81,"cat":"Direito","title":"Tutela de urgência: socorro antes do fim","idea":"É como usar um guarda-chuva agora, antes de acabar a tempestade.","explain":"Uma tutela provisória pode proteger direito antes da decisão final. A tutela de urgência exige elementos que evidenciem probabilidade do direito e perigo de dano ou risco ao resultado útil do processo, com disciplina e limites legais.","example":"Medida para evitar que a demora torne inútil uma decisão futura.","question":"Dois requisitos típicos da tutela de urgência são:","why":"Os elementos centrais estão no art. 300 do CPC.","law":"CPC, art. 300"},{"id":84,"cat":"Direito","title":"Recursos: pedir reexame","idea":"Recurso é tocar a campainha de uma instância ou órgão competente para pedir reavaliação.","explain":"O CPC lista recursos no art. 994, incluindo apelação e agravo de instrumento. Apelação, em regra, é interposta contra sentença (art. 1.009); agravo de instrumento cabe contra determinadas decisões interlocutórias previstas em lei.","example":"Sentença de primeiro grau: pense primeiro em apelação, depois confira exceções e regras específicas.","question":"Em regra, contra sentença no CPC cabe:","why":"A apelação é o recurso típico contra sentença.","law":"CPC, arts. 994 e 1.009"},{"id":87,"cat":"Direito","title":"Juizados Especiais Cíveis","idea":"É uma via de justiça pensada para conflitos menos complexos.","explain":"A Lei 9.099/1995 busca conciliação, simplicidade, oralidade, informalidade, economia processual e celeridade. O edital cita arts. 3º a 19. A competência e a necessidade de advogado variam conforme situação e limites legais.","example":"Conflito de consumo simples pode tramitar no Juizado, desde que preencha os requisitos legais.","question":"Qual princípio caracteriza os Juizados?","why":"A lei valoriza simplicidade, informalidade e rapidez.","law":"Lei 9.099/1995, art. 2º (princípios como contexto)"},{"id":90,"cat":"Direito","title":"Processo Penal: quem faz o quê?","idea":"É um time com papéis distintos: juiz decide, acusação acusa, defesa se defende.","explain":"No processo penal, estude juiz, Ministério Público, acusado e defensor, impedimentos/suspeições, citação e intimação, procedimentos e recursos, dentro dos artigos indicados. O direito de defesa e o devido processo são fundamentais.","example":"O magistrado não deve agir como defensor da acusação; cada agente tem função própria.","question":"Quem julga a causa penal?","why":"A função jurisdicional pertence ao juiz competente.","law":""},{"id":93,"cat":"Direito","title":"JECRIM e infrações de menor potencial ofensivo","idea":"O Juizado Especial Criminal possui ferramentas próprias para conflitos penais menos graves.","explain":"No âmbito da Lei 9.099/1995, há institutos como composição dos danos civis, transação penal e suspensão condicional do processo, conforme requisitos legais. Esses institutos não são sinônimos.","example":"Uma infração de menor potencial ofensivo pode seguir procedimento com tentativa de solução consensual quando preenchidos os requisitos.","question":"Transação penal e suspensão condicional do processo são:","why":"Cada instrumento tem disciplina legal própria.","law":"Lei 9.099/1995, arts. 60–89 previstos no edital"},{"id":96,"cat":"Direito","title":"Citação penal e defesa","idea":"Ninguém deve ser julgado sem a oportunidade de saber da acusação e se defender.","explain":"O CPP disciplina formas de citação e intimação e procedimentos. A citação em processo penal chama o acusado; situações especiais exigem atenção ao procedimento legal. O edital cobra trechos específicos dos arts. 351 em diante.","example":"A defesa precisa ter oportunidade de conhecer os fatos imputados e participar do processo conforme a lei.","question":"Uma finalidade essencial da citação do acusado é:","why":"A ciência formal permite contraditório e ampla defesa.","law":""},{"id":99,"cat":"Direito","title":"Estatuto do servidor de SP","idea":"Imagine o manual de convivência e deveres de quem trabalha no estado.","explain":"A Lei estadual 10.261/1968 regula temas como provimento, exercício, deveres, proibições e penalidades nos artigos especificados. Leia a letra da lei, monte tabela “dever x proibição x consequência”, e verifique o texto vigente.","example":"Guardar sigilo de informações protegidas e tratar o público adequadamente são exemplos de cuidados funcionais.","question":"Para estudar o estatuto, qual estratégia é mais segura?","why":"A redação legal e as distinções entre categorias são decisivas.","law":"Lei estadual 10.261/1968, artigos do Anexo VIII"},{"id":102,"cat":"Direito","title":"Improbidade não é qualquer erro","idea":"Erro administrativo e improbidade não são automaticamente a mesma coisa.","explain":"A Lei 8.429/1992 disciplina atos de improbidade, alterada especialmente pela Lei 14.230/2021. A caracterização dos tipos exige dolo conforme a legislação vigente; avalie enriquecimento ilícito, prejuízo ao erário e violação a princípios, entre os requisitos legais.","example":"Um erro acidental de preenchimento não vira automaticamente improbidade.","question":"Qual afirmação é mais adequada à lei atual?","why":"Improbidade depende de requisitos próprios da Lei 8.429/1992.","law":"Lei 8.429/1992, redação vigente"},{"id":105,"cat":"Direito","title":"Legislação interna: regras da casa","idea":"O TJ possui também regras para organizar seus sistemas e servidores.","explain":"O edital de 2026 inclui Resolução TJSP 850/2021 (teletrabalho), 963/2025 (governança e utilização do eproc), LC 1.111/2010 (carreira), Regimento Interno e trechos das Normas da Corregedoria. Aqui a banca pode cobrar disposições literais.","example":"Eproc é um sistema ligado à tramitação eletrônica; a resolução específica trata de sua governança e uso no TJSP.","question":"Qual norma do edital aborda teletrabalho no TJSP?","why":"A Resolução TJSP 850/2021 regula teletrabalho.","law":"Edital 02/2026, Anexo VIII, seção 6"},{"id":108,"cat":"Direito","title":"Normas da Corregedoria e eproc","idea":"Pense em um manual de organização da secretaria judicial.","explain":"As Normas da Corregedoria padronizam rotinas, documentação, fluxo e organização do serviço judicial. Já a Resolução 963/2025 trata de governança e uso do eproc. Estude os capítulos e seções delimitados, sempre no texto oficial.","example":"Questões podem perguntar quem registra determinada movimentação ou qual providência é prevista pela norma.","question":"Se a questão exigir a atribuição específica de um setor, você deve:","why":"A competência administrativa específica está na legislação interna.","law":"Normas da Corregedoria TJSP; Res. 963/2025"},{"id":111,"cat":"Lógica","title":"Proposição: frase que pode ser verdadeira ou falsa","idea":"Proposição é uma lâmpada: ou ligada (V), ou desligada (F).","explain":"“São Paulo fica no Brasil” é proposição. “Feche a porta!” é ordem e não recebe valor de verdade no mesmo sentido. Em lógica de concurso, identifique frases declarativas com valor de verdade.","example":"“5 é par” é proposição falsa; ainda é uma proposição.","question":"Qual é proposição?","why":"A igualdade é declaração avaliável como verdadeira.","law":""},{"id":114,"cat":"Lógica","title":"Se P, então Q","idea":"É um dominó: quando P ocorre, Q deve ocorrer.","explain":"Na condicional “Se P, então Q”, a única situação que torna a frase falsa é P verdadeiro com Q falso. A contrapositiva “Se não Q, então não P” é equivalente à original. Não inverta sem cuidado.","example":"Se chove, rua molha. Rua não molhou → não choveu (dentro da premissa idealizada). Rua molhou NÃO prova que choveu.","question":"Se houve distribuição, houve número. Não houve número. Então:","why":"É a contrapositiva válida: não Q → não P.","law":""},{"id":117,"cat":"Lógica","title":"E, OU, NÃO","idea":"Conectivos funcionam como botões combinados.","explain":"“P E Q” só é verdadeiro se ambos forem verdadeiros. “P OU Q” (ou inclusivo) é verdadeiro se pelo menos um for verdadeiro. “NÃO P” inverte. A Vunesp pode pedir tabela-verdade ou negações.","example":"“Ana trabalha E estuda”: basta uma parte falsa para a conjunção ser falsa.","question":"A frase “P e Q” é verdadeira quando:","why":"A conjunção exige as duas proposições verdadeiras.","law":""},{"id":120,"cat":"Lógica","title":"Negar “todos” e “alguns”","idea":"Para negar “todos têm”, basta encontrar UM que não tenha.","explain":"Negação de “todos são A” = “algum não é A”; negação de “algum é A” = “nenhum é A”. “Nenhum” = “todos não”. Use desenhos de conjuntos para visualizar.","example":"“Todos passaram” é negada por “Pelo menos uma pessoa não passou”, e NÃO por “Ninguém passou”.","question":"Negação de “Todos os processos terminaram”:","why":"Um único contraexemplo basta para negar a universal.","law":""},{"id":123,"cat":"Lógica","title":"Diagramas e conjuntos","idea":"Imagine círculos de brinquedos: um círculo para cães e outro para animais.","explain":"“Todo A é B” coloca A inteiramente dentro de B. “Algum A é B” informa interseção. “Nenhum A é B” informa círculos disjuntos. Conclusões precisam valer em todos os desenhos compatíveis.","example":"Todos os escreventes são servidores; Joana é escrevente → Joana é servidora.","question":"Todos os gatos são mamíferos. Mimi é gato. Logo:","why":"Aplicação direta da relação de inclusão.","law":""},{"id":126,"cat":"Lógica","title":"Sequências: encontre a regra","idea":"Olhe os degraus entre números antes de adivinhar o próximo.","explain":"Teste diferenças, multiplicações, alternância e agrupamentos. Em sequências de letras, cheque posições no alfabeto. Em figuras, observe rotação, número de formas ou preenchimento.","example":"2, 5, 8, 11… soma sempre 3. Próximo: 14.","question":"Qual vem depois de 3, 6, 12, 24?","why":"Cada termo é o dobro do anterior.","law":""},{"id":129,"cat":"Lógica","title":"Problemas de relações","idea":"É detetive com pistas: anote os personagens e elimine impossibilidades.","explain":"Monte tabela com linhas (pessoas) e colunas (objetos/horários), marque ✓ e ×. Leia “apenas”, “exatamente”, “antes”, “depois”. Volte para checar se usou todas as pistas.","example":"Ana não é do turno da manhã; Bruno é da manhã. Então Ana precisa de outro turno, no problema de turnos exclusivos.","question":"Com apenas Ana e Bruno, um em cada turno, Bruno está de manhã. Ana está:","why":"Com dois turnos exclusivos, o outro sobra para Ana.","law":""},{"id":132,"cat":"Matemática","title":"Porcentagem: pedaços de 100","idea":"Por cento significa “de cada cem”.","explain":"10% = 0,10; 25% = 1/4; 50% = metade. Para encontrar 15% de 200, multiplique 200 × 0,15 = 30. Para desconto, subtraia; para aumento, some.","example":"Desconto de 20% sobre R$ 150: 150 × 0,20 = 30; preço final R$ 120.","question":"25% de 240 é:","why":"Um quarto de 240 = 60.","law":""},{"id":135,"cat":"Matemática","title":"Porcentagem sucessiva","idea":"Quando um preço muda, a próxima porcentagem usa o preço NOVO.","explain":"Comece com 100. Desconto de 20% → 80. Aumento de 20% sobre 80 → 96. Portanto, uma queda de 20% e uma alta de 20% não se anulam.","example":"240 processos: resolve 25% → restam 180; resolve 20% de 180 → restam 144.","question":"Depois de reduzir 100 em 10%, sobra:","why":"100 − 10 = 90.","law":""},{"id":138,"cat":"Matemática","title":"Regra de três: quanto mais, quanto mais?","idea":"Uma receita para 2 pessoas pode ser dobrada para 4.","explain":"Grandezas diretamente proporcionais: uma cresce e a outra cresce na mesma razão. Inversamente proporcionais: uma cresce e a outra diminui. Identifique antes de multiplicar cruzado.","example":"12 processos em 3 horas → 4 por hora → em 5 horas, 20 processos.","question":"12 processos em 3 horas, mesmo ritmo. Em 5 horas:","why":"4 processos por hora × 5 = 20.","law":""},{"id":141,"cat":"Matemática","title":"Média simples e ponderada","idea":"Média é dividir igualmente uma pilha de pontos.","explain":"Média simples = soma ÷ quantidade. Média ponderada = soma dos produtos valor × peso ÷ soma dos pesos. Leia o enunciado: notas com pesos diferentes pedem ponderada.","example":"Notas 6 (peso 1) e 8 (peso 2): (6×1 + 8×2)/3 = 22/3 ≈ 7,33.","question":"Média simples de 4, 6 e 8 é:","why":"(4+6+8)/3 = 18/3 = 6.","law":""},{"id":144,"cat":"Matemática","title":"Equação: a balança","idea":"Se tirou algo de um lado, tire do outro também.","explain":"Resolver 3x + 5 = 20: subtraia 5 em ambos os lados → 3x=15; divida por 3 → x=5. Equações de segundo grau podem exigir fatoração ou fórmula. Sistemas pedem encontrar valores que satisfazem todas as equações.","example":"2x − 4 = 10 → 2x=14 → x=7.","question":"Se 2x+6=16, x vale:","why":"2x=10; x=5.","law":""},{"id":147,"cat":"Matemática","title":"MMC e MDC: encontros e divisões","idea":"MMC ajuda a encontrar quando eventos voltam a coincidir; MDC divide em grupos iguais sem sobrar.","explain":"MMC: menor múltiplo comum positivo. MDC: maior divisor comum. Exemplo: alarmes a cada 4 e 6 minutos coincidem novamente após 12 minutos. Dividir 24 e 36 em grupos iguais máximos leva ao MDC 12.","example":"Ônibus a cada 10 e 15 min: coincidência após 30 min.","question":"MMC(4,6) é:","why":"Múltiplos de 4: 4,8,12; de 6: 6,12. Primeiro encontro: 12.","law":""},{"id":150,"cat":"Matemática","title":"Juros simples","idea":"Em juros simples, o acréscimo por período tem base fixa.","explain":"J = C × i × t. C capital, i taxa decimal por período, t número de períodos na mesma unidade. Montante M = C + J. Se capital é 1.000, taxa 2% ao mês por 3 meses: J=1000×0,02×3=60.","example":"R$ 500 a 1% ao mês por 4 meses → juros R$ 20.","question":"Juros simples de R$ 200 a 5% ao mês por 2 meses:","why":"200×0,05×2=20.","law":""},{"id":153,"cat":"Matemática","title":"Geometria e tabelas","idea":"Geometria mede chão, borda, caixa e distância.","explain":"Perímetro: contorno. Área: superfície. Volume: espaço ocupado. Retângulo: área = base×altura. Triângulo: área = base×altura/2. Pitágoras em triângulo retângulo: a²+b²=c². Leia unidades.","example":"Sala 4 m × 3 m: área 12 m², perímetro 14 m.","question":"Área de retângulo 5 m × 2 m:","why":"5×2=10 m².","law":""},{"id":156,"cat":"Informática","title":"Windows: arquivos e pastas","idea":"Pastas são gavetas; arquivos são as folhas guardadas nelas.","explain":"Conheça copiar, mover, renomear, excluir, extensão, atalhos e área de transferência. Um atalho aponta para algo; não é necessariamente o próprio arquivo. Explorar arquivos no Windows exige atenção ao caminho e à extensão.","example":"Relatório.docx é documento; Relatório.xlsx é planilha; um atalho pode apontar para qualquer um deles.","question":"Um arquivo .xlsx costuma ser:","why":"A extensão xlsx é usada por planilhas do Excel.","law":""},{"id":159,"cat":"Informática","title":"Word: revisão de texto","idea":"Controlar alterações é como colocar etiquetas em cada mudança feita num livro.","explain":"No Word, veja estilos, formatação, tabelas, cabeçalho, numeração, quebras, sumário e Controlar Alterações. Comentários registram observações; comparar documentos ajuda a identificar diferenças entre versões.","example":"Editor muda uma frase e o autor pode aceitar ou rejeitar a alteração.","question":"Qual ferramenta registra edições para revisão?","why":"É o recurso apropriado para rastrear mudanças.","law":""},{"id":162,"cat":"Informática","title":"Excel: fórmula é receita","idea":"Planilha é tabela que calcula sozinha usando receitas.","explain":"Toda fórmula começa com “=”. “=SOMA(A1:A3)” soma intervalo. A referência A1 aponta coluna A e linha 1. Ao copiar fórmula, referências relativas podem mudar. O $ fixa coluna ou linha conforme posição.","example":"Em C2: =$A2*B$1. Copiando uma coluna à direita e uma linha abaixo → =$A3*C$1.","question":"Ao copiar =$A2*B$1 de C2 para D3, vira:","why":"A fica fixa, linha 2 vira 3; B vira C, linha 1 fica fixa.","law":""},{"id":165,"cat":"Informática","title":"Excel: SE e filtros","idea":"SE é um porteiro: se uma condição é cumprida, faz A; se não, faz B.","explain":"Exemplo: =SE(A2>=7;\"Aprovado\";\"Revisar\") em planilha pt-BR. Filtros ocultam temporariamente linhas fora do critério, sem apagá-las. Formatação condicional colore células de acordo com regras.","example":"Planilha de prazos: data vencida e ainda não paga → destaque visual.","question":"Qual ferramenta destaca automaticamente prazos vencidos?","why":"Ela aplica formatos por condições.","law":""},{"id":168,"cat":"Informática","title":"Internet, URL e phishing","idea":"URL é endereço de uma casa online; phishing é uma carta falsa querendo roubar chave.","explain":"Entenda domínio, endereço web, link, navegador e HTTPS. HTTPS protege a conexão, mas não garante que um site seja legítimo. Cuidado com mensagens que pedem senha ou urgência e links parecidos com sites oficiais.","example":"“tribunal-seguro-exemplo.com” não vira oficial só porque tem “tribunal” no nome.","question":"Qual atitude é mais segura?","why":"Verificar origem e domínio ajuda a evitar phishing.","law":""},{"id":171,"cat":"Informática","title":"E-mail: CC, CCO e anexos","idea":"CCO é como mandar cópias sem mostrar os outros endereços.","explain":"Para = destinatários principais; CC = cópia visível; CCO = cópia oculta. Conheça anexar, responder, responder a todos, encaminhar, spam e links. Atenção à proteção de dados em comunicação institucional.","example":"Aviso para destinatários externos sem expor a lista: avalie CCO.","question":"Qual campo oculta destinatários dos demais?","why":"CCO é cópia oculta.","law":""},{"id":174,"cat":"Informática","title":"Teams, OneDrive e colaboração","idea":"OneDrive é armário de arquivos na nuvem; Teams é sala virtual de trabalho.","explain":"No Microsoft 365, Teams oferece conversas e reuniões; OneDrive guarda e compartilha arquivos, com permissões. Word/Excel podem permitir colaboração em documentos, conforme a configuração. Saiba diferenciar editar e visualizar.","example":"Se você só quer que colega leia, compartilhe com permissão de visualização.","question":"Para permitir leitura sem edição, use permissão:","why":"Visualização limita alterações.","law":""},{"id":177,"cat":"Gerais","title":"Atualidades: como estudar fatos sem decorar manchetes","idea":"Notícia é uma peça de quebra-cabeça: contexto é a imagem da caixa.","explain":"O edital abrange fatos políticos, econômicos, sociais e culturais nacionais e internacionais a partir do primeiro semestre de 2026. Para cada tema, responda: o que aconteceu? quando? quais atores? por que importa? qual consequência? Consulte fontes confiáveis e atualizadas.","example":"Tema político: identifique instituição, decisão, repercussão e diferença entre notícia e opinião.","question":"Qual é melhor forma de revisar atualidades?","why":"A prova costuma cobrar compreensão e contextualização.","law":""},{"id":180,"cat":"Gerais","title":"Estatuto da Pessoa com Deficiência","idea":"Acessibilidade é remover barreiras para que pessoas participem em igualdade.","explain":"A Lei 13.146/2015 trata de direitos, acessibilidade, inclusão e igualdade de oportunidades. O edital delimita arts. 1º–13 e 34–38. Estude conceitos de deficiência, barreiras, discriminação, autonomia e direitos no trabalho.","example":"Um sistema público que oferece recursos acessíveis reduz barreiras à participação.","question":"A inclusão busca principalmente:","why":"A lei busca inclusão e participação em igualdade.","law":"Lei 13.146/2015, arts. 1º–13 e 34–38"},{"id":183,"cat":"Redação","title":"Redação: a arquitetura do texto","idea":"Escrever uma dissertação é construir casa: entrada, cômodos, saída.","explain":"A redação pede texto dissertativo-argumentativo. Estrutura funcional: introdução com tema e tese; desenvolvimento 1 com argumento; desenvolvimento 2 com outro argumento; conclusão que amarra o raciocínio. Leia sempre a proposta da prova.","example":"Tema hipotético: “tecnologia e acesso à Justiça”. Tese: soluções digitais ampliam acesso, mas precisam ser acompanhadas de inclusão digital.","question":"Uma tese serve para:","why":"É a ideia central sustentada ao longo do texto.","law":"Edital 02/2026, capítulo XI"},{"id":186,"cat":"Redação","title":"Como transformar opinião em argumento","idea":"Opinião é “acho”; argumento é “acho por causa de X, que produz Y”.","explain":"Use um caminho: afirmação → explicação → exemplo plausível → ligação com a tese. Faça parágrafos claros, sem exagero retórico, respeitando o tema. Citações são opcionais: argumento bem explicado vale mais que frase famosa sem contexto.","example":"“A acessibilidade digital é essencial” → porque serviços eletrônicos sem recursos inclusivos podem excluir usuários → isso compromete acesso igualitário.","question":"O que fortalece um argumento?","why":"A coerência entre explicação e tese constrói força argumentativa.","law":""},{"id":189,"cat":"Redação","title":"Revisão final: 5 perguntas","idea":"Revise a redação como revisor de um jornal.","explain":"Confira: (1) respondi ao tema? (2) tenho tese clara? (3) cada parágrafo acrescenta algo? (4) concordância, pontuação e ortografia estão adequadas? (5) dá para ler facilmente? O edital informa que textos muito curtos têm restrições na pontuação e que não é necessária proposta de intervenção.","example":"Antes de entregar, releia cada frase procurando sujeito, verbo e conectivo.","question":"A redação exige necessariamente proposta de intervenção ao estilo ENEM?","why":"O edital afirma que não é necessária uma conclusão com proposta de intervenção.","law":"Edital 02/2026, capítulo XI"},{"id":192,"cat":"Estratégia","title":"Como estudar Direito sem decorar tudo de uma vez","idea":"Suba escada por degraus: conceito → exemplo → artigo → questão.","explain":"Faça uma ficha por artigo importante: “quem?”, “conduta?”, “exceção?”, “consequência?”. Para Penal, compare tipos próximos; para Processo, desenhe fluxogramas; para legislação interna, use leitura literal e quadro de responsabilidades.","example":"Concussão x corrupção passiva: destaque “exigir” versus “solicitar/receber/aceitar promessa”.","question":"Qual sequência é mais sólida?","why":"Aprendizagem com compreensão, fonte e aplicação é mais robusta.","law":""},{"id":195,"cat":"Estratégia","title":"Revisão inteligente em 1, 3 e 7 dias","idea":"Lembrança é como trilha na mata: pisar nela de novo mantém o caminho aberto.","explain":"Depois de aprender, tente explicar com suas palavras no dia seguinte, três dias depois e sete dias depois. Resolva uma questão nova de cada tema. Refaça apenas os itens errados. Aqui você pode sinalizar que estudou e marcar slides para revisar.","example":"Se errou crase, volte ao teste masculino e tente outra frase, sem reler toda a gramática.","question":"Depois de errar, o melhor é:","why":"Entender a causa do erro evita repeti-lo.","law":""},{"id":198,"cat":"Estratégia","title":"Dia da prova: como gerir cinco horas","idea":"Seu tempo é um orçamento: não gaste tudo numa única questão.","explain":"A prova tem 70 itens + redação em até cinco horas. Reserve tempo para leitura, passagem de respostas e redação. Uma sugestão ajustável: 3h10 para objetiva, 1h25 para redação e 25 min para preencher/revisar; teste em simulado e ajuste.","example":"Uma questão travou por 4 minutos? Marque para retornar, avance e preserve tempo para redação.","question":"Se uma questão travar, geralmente é melhor:","why":"Preservar tempo para outras questões e redação tende a ser mais seguro.","law":""},{"id":201,"cat":"Português","title":"Fato, opinião e inferência","idea":"Uma informação escrita é como uma peça de quebra-cabeça; a conclusão precisa encaixar nas peças disponíveis.","explain":"Fato é algo verificável; opinião avalia ou julga; inferência decorre de pistas. A Vunesp pode apresentar uma alternativa plausível, mas que extrapola o texto. Procure o trecho que sustenta sua escolha.","example":"Texto: “O tribunal ampliou os canais digitais.” Fato: houve ampliação. Não se pode concluir que o atendimento presencial acabou.","question":"Qual conclusão é segura sobre “Alguns usuários preferem atendimento online”?","why":"“Alguns” não significa “todos”.","law":""},{"id":204,"cat":"Português","title":"Ambiguidade e reescrita","idea":"Duas interpretações possíveis são como uma placa que aponta para dois caminhos.","explain":"Ambiguidade pode nascer do posicionamento de adjuntos, pronomes e pontuação. Em reescritas, confira se o sentido, os sujeitos e as relações lógicas foram mantidos.","example":"“O chefe avisou o servidor de que ele seria promovido.” Quem seria promovido? O pronome pode criar dúvida.","question":"Qual reescrita elimina a ambiguidade?","why":"A fala direta identifica quem será promovido.","law":""},{"id":207,"cat":"Português","title":"Orações subordinadas: causa, condição e concessão","idea":"Uma oração explica por que, quando ou apesar de quê outra acontece.","explain":"Causais: porque, já que. Condicionais: se, caso. Concessivas: embora, mesmo que. Temporais: quando, assim que. A relação não depende só da palavra isolada; leia as duas orações.","example":"“Se houver vaga, serei chamado” apresenta condição, não uma garantia de chamada.","question":"Em “Caso o documento chegue, analisaremos”, “caso” expressa:","why":"A análise fica condicionada ao recebimento.","law":""},{"id":210,"cat":"Português","title":"Voz ativa e voz passiva","idea":"Na ativa, alguém pratica a ação; na passiva, o foco vai para o alvo da ação.","explain":"Ativa: “O cartório publicou a decisão.” Passiva: “A decisão foi publicada pelo cartório.” O tempo verbal e a relação agente/paciente devem ser preservados na transformação.","example":"“Os servidores revisaram os autos” → “Os autos foram revisados pelos servidores”.","question":"Qual é a passiva de “A equipe conferiu o documento”?","why":"O objeto “documento” vira sujeito paciente.","law":""},{"id":213,"cat":"Português","title":"Concordância nominal e paralelismo","idea":"As palavras que acompanham o nome precisam combinar com ele.","explain":"Adjetivos e artigos concordam em gênero e número, observadas construções especiais. Em listas, paralelismo mantém estruturas equivalentes: “analisar processos, redigir documentos e atender usuários”.","example":"“As certidões anexas” (adjetivo plural); “documentos em anexo” (locução).","question":"Qual expressão está correta?","why":"“Anexas” concorda com “cópias”.","law":""},{"id":216,"cat":"Português","title":"Pronomes relativos","idea":"O relativo evita repetição e liga duas informações sobre o mesmo nome.","explain":"“O documento que chegou” retoma “documento”. “Cujo” indica posse e não recebe artigo depois: “autor cujo livro...”. “Onde” remete a lugar; “aonde”, com movimento e verbo que pede “a”.","example":"“A cidade onde trabalho”; “A cidade aonde irei”.","question":"Qual construção está adequada?","why":"“Cujo” indica posse sem artigo após ele.","law":""},{"id":219,"cat":"Português","title":"Regência verbal: assistir, visar e aspirar","idea":"Um mesmo verbo pode mudar de preposição conforme o sentido.","explain":"Assistir no sentido de ver pede “a” na norma-padrão. Visar no sentido de almejar geralmente pede “a”; visar no sentido de pôr visto é transitivo direto. Aspirar no sentido de desejar pede “a”; de inalar é direto.","example":"“Assistimos ao julgamento”; “aspira ao cargo”; “aspirou o ar”.","question":"No sentido de presenciar, qual está correta?","why":"A construção normativa é assistir a + a audiência = à audiência.","law":""},{"id":222,"cat":"Português","title":"Colocação pronominal","idea":"A posição do pronome muda segundo fatores de atração e início de frase.","explain":"Próclise: antes (“não me avisaram”). Ênclise: depois (“avisaram-me”). Mesóclise: no meio de futuro, em contextos formais (“avisar-me-ão”). Palavras negativas, relativos e certos advérbios atraem a próclise.","example":"“Jamais se esqueceram do prazo”: “jamais” atrai “se”.","question":"Qual segue a norma-padrão?","why":"O termo negativo “nunca” atrai o pronome.","law":""},{"id":225,"cat":"Português","title":"Pontuação do aposto e vocativo","idea":"Quem explica e quem é chamado podem ficar entre vírgulas.","explain":"Aposto explicativo acrescenta informação; vocativo chama uma pessoa. Não separe o sujeito do verbo só porque ele é longo. Ponto e vírgula pode separar partes de enumerações extensas.","example":"“Carlos, escrevente do fórum, chegou.” (aposto) e “Carlos, venha aqui.” (vocativo).","question":"Em “Ana, revise o relatório”, “Ana” é:","why":"É a pessoa chamada pelo falante.","law":""},{"id":228,"cat":"Português","title":"Semântica: pressuposto e subentendido","idea":"Às vezes o texto informa algo sem declarar diretamente.","explain":"“O servidor voltou a estudar” pressupõe que ele já estudava antes. Pressupostos costumam ser ativados por “voltar a”, “deixar de”, “ainda”. Subentendido depende mais do contexto e pode não ser obrigatório.","example":"“Ela parou de reclamar” pressupõe que reclamava.","question":"“Ele deixou de faltar” pressupõe que:","why":"“Deixar de” pressupõe a ocorrência anterior.","law":""},{"id":231,"cat":"Direito","title":"CF: legalidade, liberdade e igualdade","idea":"A Constituição é uma regra de proteção tanto para o cidadão quanto para o Estado.","explain":"Art. 5º: ninguém será obrigado a fazer ou deixar de fazer algo senão em virtude de lei. A igualdade perante a lei convive com tratamentos diferenciados justificáveis para efetivar direitos. Estude também inviolabilidade da intimidade e devido processo legal.","example":"O Estado não pode inventar obrigação sem fundamento legal.","question":"Qual regra expressa a legalidade do art. 5º?","why":"A legalidade limita imposições ao cidadão.","law":"CF/1988, art. 5º"},{"id":234,"cat":"Direito","title":"CF: habeas corpus, mandado de segurança e habeas data","idea":"São ferramentas diferentes dentro da mesma caixa de proteção.","explain":"Habeas corpus protege liberdade de locomoção. Mandado de segurança protege direito líquido e certo não amparado por HC ou HD. Habeas data possibilita conhecer ou retificar informações pessoais em bancos públicos ou de caráter público.","example":"Ameaça ilegal de prisão: pense em habeas corpus; dado pessoal incorreto em cadastro público: habeas data.","question":"Qual remédio protege a liberdade de ir e vir?","why":"HC protege a liberdade de locomoção.","law":"CF/1988, art. 5º, LXVIII–LXXII"},{"id":237,"cat":"Direito","title":"CF: direitos do trabalhador e direitos sociais","idea":"O Estado reconhece necessidades básicas da vida coletiva.","explain":"Art. 6º trata dos direitos sociais; art. 7º enumera direitos de trabalhadores urbanos e rurais, observadas exceções e regimes. Não confunda direitos sociais com nacionalidade e direitos políticos.","example":"Educação, saúde, alimentação e moradia constam do catálogo de direitos sociais.","question":"Qual é direito social previsto no art. 6º?","why":"Educação integra o rol constitucional de direitos sociais.","law":"CF/1988, arts. 6º e 7º"},{"id":240,"cat":"Direito","title":"CF: administração pública e concurso","idea":"Cargo efetivo geralmente exige aprovação em concurso, mas há regras e exceções.","explain":"Art. 37 apresenta princípios e disciplina concurso, prazo de validade, cargos em comissão e funções de confiança. Nomeação não decorre automaticamente de aprovação em cadastro de reserva; jurisprudência e edital importam.","example":"Cargo em comissão destina-se a direção, chefia e assessoramento; não substitui funções comuns de toda repartição.","question":"Qual princípio constitucional inclui impessoalidade?","why":"A impessoalidade está no LIMPE do art. 37.","law":"CF/1988, art. 37"},{"id":243,"cat":"Direito","title":"Direito Administrativo: atos e competência","idea":"Um ato administrativo é uma decisão pública que precisa seguir regras.","explain":"Verifique competência, finalidade, forma, motivo e objeto. Competência indica quem pode agir; finalidade atende ao interesse público. Vícios podem gerar invalidação, sempre observadas as normas aplicáveis.","example":"Um servidor sem competência não pode decidir sozinho um assunto reservado ao juiz.","question":"O elemento que responde “quem pode praticar o ato?” é:","why":"Competência indica o agente legalmente autorizado.","law":""},{"id":246,"cat":"Direito","title":"Administração: anulação e revogação","idea":"Uma coisa é corrigir ilegalidade; outra é alterar uma escolha válida.","explain":"Anulação enfrenta ilegalidade. Revogação atua sobre conveniência/oportunidade de ato válido, quando juridicamente possível. Controle judicial de legalidade não equivale à gestão da conveniência da Administração.","example":"Se um ato foi praticado contra lei, estuda-se anulação; se ato válido perdeu utilidade, revogação pode ser considerada.","question":"Um ato ilegal deve ser enfrentado, em regra, por:","why":"A anulação trata do vício de legalidade.","law":""},{"id":249,"cat":"Direito","title":"Administração: agente público e deveres","idea":"Quem usa recursos do Estado responde a padrões de atuação.","explain":"Servidor estatutário, empregado público e agente político são categorias diferentes. Regras do estatuto disciplinam deveres, proibições, responsabilidades e sanções. Na prova, leia quem praticou o ato e qual dever específico foi violado.","example":"Receber presente indevido em troca de favor pode ter consequências administrativas e penais, conforme o caso.","question":"Qual comportamento se alinha aos deveres do servidor?","why":"Zelo e observância de regras sustentam o serviço público.","law":"Lei estadual SP 10.261/1968"},{"id":252,"cat":"Direito","title":"Lei 10.261: posse, exercício e provimento","idea":"Entrar no cargo é uma sequência com etapas diferentes.","explain":"Provimento é a forma de preenchimento. Nomeação designa o candidato; posse formaliza a investidura; exercício é o início efetivo das atividades, conforme prazos legais. O edital e o Estatuto estadual estabelecem requisitos e procedimentos.","example":"Ser nomeado hoje não significa ter começado a trabalhar hoje.","question":"Qual etapa representa o início efetivo do trabalho?","why":"Exercício é o início do desempenho das atribuições.","law":"Lei SP 10.261/1968, arts. 1º–86"},{"id":255,"cat":"Direito","title":"Lei 10.261: licenças e afastamentos","idea":"Licença não é folga concedida só pela vontade do servidor.","explain":"A lei prevê hipóteses, requisitos, prazos e procedimentos para licenças e afastamentos. Identifique motivo, autoridade competente e necessidade de documentação; estude literalmente os dispositivos do edital.","example":"Uma licença para tratamento de saúde depende de requisitos legais e avaliação quando prevista.","question":"Em licença estatutária, o essencial é conferir:","why":"Cada licença tem disciplina legal própria.","law":"Lei SP 10.261/1968, arts. 171–175 e correlatos previstos"},{"id":258,"cat":"Direito","title":"Penal: peculato, apropriação e desvio","idea":"Usar coisa confiada ao cargo como se fosse sua quebra a confiança pública.","explain":"Peculato (CP art. 312) envolve apropriar-se ou desviar dinheiro, valor ou bem móvel, público ou particular, de que o agente tem posse em razão do cargo. Outras modalidades previstas no artigo exigem atenção.","example":"Servidor desvia valores sob sua guarda funcional para beneficiar terceiro.","question":"Peculato por apropriação exige, no núcleo principal:","why":"O vínculo funcional com a posse é decisivo.","law":"CP, art. 312"},{"id":261,"cat":"Direito","title":"Penal: concussão, corrupção e prevaricação","idea":"Exigir, solicitar, receber e atrasar por interesse próprio são verbos-chave.","explain":"Concussão (316): exigir vantagem indevida. Corrupção passiva (317): solicitar/receber vantagem ou aceitar promessa, nos termos legais. Prevaricação (319): retardar, deixar de praticar ou praticar indevidamente ato de ofício para satisfazer interesse ou sentimento pessoal.","example":"“Só libero se me pagar” sugere exigência; “me dá algo?” sugere solicitação.","question":"O servidor EXIGE vantagem indevida por causa do cargo:","why":"Exigir é verbo nuclear da concussão.","law":"CP, arts. 316–319"},{"id":264,"cat":"Direito","title":"Penal: falsificação material e ideológica","idea":"Uma coisa é mudar o papel; outra é mentir no conteúdo verdadeiro do papel.","explain":"Falsidade material envolve adulterar ou fabricar documento. Falsidade ideológica (299) pode consistir em inserir/deixar de inserir declaração falsa relevante em documento formalmente verdadeiro, nas condições do tipo.","example":"Documento autêntico em sua forma, mas declaração falsa sobre fato juridicamente relevante: investigue falsidade ideológica.","question":"O documento é formalmente autêntico mas traz declaração falsa relevante:","why":"É o contraste didático entre forma do documento e conteúdo declarado.","law":"CP, arts. 297–299"},{"id":267,"cat":"Direito","title":"Penal: crimes contra a justiça","idea":"A própria investigação e a decisão precisam de proteção.","explain":"O edital inclui tipos envolvendo denunciação caluniosa, comunicação falsa, falso testemunho e outros atos contra a administração da justiça. Identifique a conduta e os requisitos legais, inclusive conhecimento da inocência quando exigido.","example":"Provocar investigação imputando falsamente crime a pessoa sabidamente inocente pode configurar denunciação caluniosa, observados os elementos do art. 339.","question":"Quando alguém sabe ser inocente a pessoa a quem atribui crime para provocar investigação, estude:","why":"O art. 339 protege a administração da justiça.","law":"CP, art. 339"},{"id":270,"cat":"Direito","title":"Processo civil: petição inicial e defesa","idea":"A ação é uma conversa formal com regras de entrada e resposta.","explain":"Petição inicial apresenta partes, fatos, fundamentos, pedidos e demais requisitos legais. Pode ser necessário emendar. Citação chama o réu; contestação é uma defesa usual. O juiz organiza o processo e decide, conforme regras do CPC.","example":"A petição traz o que se pede; a contestação responde aos argumentos.","question":"Qual peça normalmente inicia uma ação civil comum?","why":"É o instrumento típico de instauração da demanda.","law":"CPC, arts. 318–343"},{"id":273,"cat":"Direito","title":"Processo civil: revelia e saneamento","idea":"Não responder ao processo pode ter efeitos, mas há exceções.","explain":"Revelia decorre, em regra, da ausência de contestação; efeitos sobre alegações de fato dependem das hipóteses legais. Saneamento organiza pontos controvertidos e provas. Leia as exceções antes de concluir que “ganha automaticamente”.","example":"Réu não contesta; o juiz ainda precisa observar as regras e analisar o caso.","question":"Qual afirmação é correta?","why":"O CPC prevê limites e exceções aos efeitos da revelia.","law":"CPC, arts. 344–357"},{"id":276,"cat":"Direito","title":"Processo civil: recursos e prazos","idea":"Recurso é pedir nova análise por meio previsto na lei.","explain":"CPC contém modalidades como apelação, agravo de instrumento e embargos de declaração. Cada uma tem finalidade e pressupostos específicos. Prazos e contagem exigem atenção à regra vigente e a eventuais exceções.","example":"Embargos de declaração tratam, em regra, de obscuridade, contradição, omissão ou erro material.","question":"Qual recurso se volta a omissão ou contradição da decisão?","why":"Embargos de declaração têm hipóteses específicas no CPC.","law":"CPC, arts. 994–1026"},{"id":279,"cat":"Direito","title":"Processo civil: tutela provisória","idea":"Quando esperar pode causar dano, a lei prevê decisões provisórias.","explain":"Tutela provisória pode ser de urgência ou evidência, conforme requisitos. Na tutela de urgência, atente a probabilidade do direito e perigo de dano ou risco ao resultado útil do processo. Não é julgamento definitivo do mérito.","example":"Medicamento urgente, com documentos que indiquem plausibilidade e risco, pode justificar análise de tutela de urgência.","question":"Em regra, tutela de urgência exige:","why":"São os requisitos centrais do art. 300.","law":"CPC, art. 300"},{"id":282,"cat":"Direito","title":"Processo civil: impedimento e suspeição","idea":"Quem julga deve ser imparcial, e a lei cria filtros.","explain":"Impedimento é hipótese objetiva legal de afastamento do julgador; suspeição trata situações indicadas pelo CPC que comprometem confiança na imparcialidade. O edital inclui artigos sobre o tema.","example":"Juiz com relação legalmente impeditiva não deve atuar no feito.","question":"O objetivo das regras de impedimento e suspeição é:","why":"O processo precisa de julgador imparcial.","law":"CPC, arts. 144–148"},{"id":285,"cat":"Direito","title":"Processo penal: inquérito e ação penal","idea":"Investigar não é a mesma coisa que julgar.","explain":"Inquérito investiga fatos e autoria, sem ser processo de condenação. Ação penal leva a acusação ao Judiciário. Distinga atribuições de polícia, Ministério Público, juiz e defesa.","example":"Uma investigação pode gerar elementos para decisão de oferecer denúncia, sem significar culpabilidade automática.","question":"Qual afirmação é correta?","why":"As etapas e funções são distintas.","law":""},{"id":288,"cat":"Direito","title":"Processo penal: citação, intimação e defesa","idea":"Ninguém deve responder a processo sem meios regulares de saber e defender-se.","explain":"Citação chama o acusado a integrar a relação processual; intimação comunica atos. Os dispositivos do edital tratam de formas e efeitos, inclusive editalícia quando cabível. A defesa técnica integra o devido processo.","example":"Acusado precisa ser regularmente citado; depois, comunicações de atos seguem regras próprias.","question":"Qual ato chama formalmente o acusado ao processo?","why":"Citação estabelece a ciência formal inicial.","law":"CPP, arts. 351–372"},{"id":291,"cat":"Direito","title":"Processo penal: procedimento comum","idea":"O processo tem sequência e oportunidades de defesa.","explain":"O CPP disciplina recebimento, resposta, instrução, provas, debates e decisão, conforme o procedimento aplicável. Não memorize apenas uma ordem genérica; algumas hipóteses têm regras próprias.","example":"Após a acusação, o rito permite defesa e produção de prova antes de eventual condenação.","question":"A instrução processual serve principalmente para:","why":"Instrução é fase de produção e avaliação de provas.","law":"CPP, arts. 394–405"},{"id":294,"cat":"Direito","title":"Juizados especiais: simplicidade com limites","idea":"Juizado busca procedimento mais simples, não ausência de regras.","explain":"Na Lei 9.099/1995 há oralidade, simplicidade, informalidade, economia processual e celeridade. Distinga área cível de criminal. Competência, valores e causas excluídas precisam de leitura literal.","example":"Pequena demanda cível admissível pode usar rito simplificado.","question":"Qual é um princípio dos juizados?","why":"A Lei 9.099 privilegia simplicidade e celeridade.","law":"Lei 9.099/1995"},{"id":297,"cat":"Direito","title":"Legislação interna: teletrabalho TJSP","idea":"Teletrabalho exige regras de produtividade e controle, não liberdade irrestrita.","explain":"Resolução TJSP 850/2021 trata do teletrabalho. Estude requisitos, atividades, acompanhamento, vedações e deveres segundo a redação vigente indicada no edital. A aplicação depende das condições da norma e das determinações administrativas.","example":"Um servidor em teletrabalho segue sujeito à produtividade, segurança e rotinas estabelecidas.","question":"Uma leitura correta da regulamentação é:","why":"O regime é regulamentado e condicionado.","law":"Resolução TJSP 850/2021"},{"id":300,"cat":"Direito","title":"Legislação interna: eproc TJSP","idea":"Processo eletrônico é um sistema de trabalho com regras de governança.","explain":"Resolução TJSP 963/2025 disciplina governança e utilização do eproc. Na preparação, diferencie sistema, unidade responsável, perfis, fluxo processual e regras de segurança conforme texto vigente.","example":"Protocolo eletrônico e movimentações precisam seguir perfis e procedimentos autorizados.","question":"A resolução 963/2025 é sobre:","why":"É norma interna especificamente vinculada ao eproc.","law":"Resolução TJSP 963/2025"},{"id":303,"cat":"Direito","title":"Legislação interna: Corregedoria e cartório","idea":"O balcão do cartório segue um manual de procedimentos.","explain":"As Normas de Serviço da Corregedoria Geral da Justiça regulam atividades e controles de unidades judiciais. O edital delimita Tomo I e seções específicas; estude a organização documental, tramitação, atendimento e procedimentos pelos dispositivos originais.","example":"Cumprir um mandado e certificar atos exigem registro e conferência conforme normas.","question":"Qual é a principal finalidade das Normas da Corregedoria?","why":"As normas estruturam o serviço judiciário.","law":"NSCGJ, Tomo I, seções do Anexo VIII"},{"id":306,"cat":"Lógica","title":"Tabela-verdade: condicional","idea":"“Se chover, então molha” só falha se chover e não molhar.","explain":"P→Q é falsa somente quando P é verdadeira e Q é falsa. Não confunda “se P então Q” com “se Q então P”. Contrapositiva: ¬Q→¬P.","example":"Se a inscrição foi homologada, então o pagamento foi confirmado. Se pagamento não foi confirmado, a contrapositiva nega a homologação, sob essa premissa.","question":"Quando P→Q é falsa?","why":"Condicional só falha no caso V→F.","law":""},{"id":309,"cat":"Lógica","title":"Negação de condicional","idea":"Para negar “se P, então Q”, mostre um caso em que P ocorreu e Q falhou.","explain":"¬(P→Q) equivale a P e ¬Q. Negar todo condicional não é trocar apenas uma palavra; a condição original precisa ocorrer e a consequência não.","example":"“Se estudar, passará” é negada por “Estudou e não passou”.","question":"Negação de “Se foi citado, compareceu”:","why":"A negação é P ∧ ¬Q.","law":""},{"id":312,"cat":"Lógica","title":"Equivalência: contrapartida lógica","idea":"Duas frases podem descrever a mesma regra de modos diferentes.","explain":"P→Q equivale à contrapositiva ¬Q→¬P e à disjunção ¬P∨Q. Monte casos quando estiver inseguro.","example":"“Se é servidor do setor, tem crachá” equivale a “Se não tem crachá, não é servidor do setor”, assumindo a premissa dada.","question":"Equivalente a “Se A, então B” é:","why":"É a contrapositiva.","law":""},{"id":315,"cat":"Lógica","title":"Contagem de possibilidades","idea":"Organizar casos é melhor do que adivinhar.","explain":"Se há 3 camisetas e 2 calças, o princípio multiplicativo gera 3×2=6 combinações quando todas são possíveis. Condições restritivas exigem excluir casos proibidos.","example":"Com 2 turnos e 3 locais possíveis, há 6 pares turno-local.","question":"3 opções de capa e 2 de fonte geram quantas combinações?","why":"São 3×2 escolhas combinadas.","law":""},{"id":318,"cat":"Matemática","title":"Razão, proporção e escala","idea":"Uma razão compara duas quantidades em uma mesma régua.","explain":"Razão a/b compara a com b. Proporção iguala duas razões. Escala 1:100 significa que 1 unidade no desenho corresponde a 100 da realidade, usando unidades coerentes.","example":"Se 2 atendentes lidam com 30 solicitações no mesmo período e ritmo, 4 atendentes lidariam com 60, nas hipóteses de proporcionalidade.","question":"Se 3 itens custam R$ 12, quanto custam 5 ao mesmo preço unitário?","why":"Cada item custa R$ 4; cinco custam R$ 20.","law":""},{"id":321,"cat":"Matemática","title":"Equação do 2º grau","idea":"Uma expressão com x² pode ter até duas soluções reais.","explain":"Na forma ax²+bx+c=0, com a≠0, use fatoração, produto notável ou fórmula quadrática. O discriminante Δ=b²−4ac informa a quantidade de raízes reais.","example":"x²−9=0 → (x−3)(x+3)=0 → x=3 ou x=−3.","question":"As raízes reais de x²−16=0 são:","why":"x²=16 implica x=±4.","law":""},{"id":324,"cat":"Matemática","title":"Sistema de equações","idea":"Duas pistas juntas permitem descobrir dois números.","explain":"Métodos: substituição ou eliminação. Ex.: x+y=10 e x−y=2. Somando: 2x=12, x=6; então y=4. Confira nas duas equações.","example":"6+4=10 e 6−4=2.","question":"Se x+y=8 e x−y=2, x é:","why":"Somando, 2x=10, x=5.","law":""},{"id":327,"cat":"Matemática","title":"Unidades e volume","idea":"Comprimento mede borda; área mede superfície; volume mede espaço.","explain":"1 m=100 cm; 1 m²=10.000 cm²; 1 m³=1.000 litros. Para um paralelepípedo, volume = comprimento×largura×altura. Cuidado: ao elevar a unidade, o fator de conversão também é elevado.","example":"Caixa 2 m×1 m×1 m ocupa 2 m³.","question":"O volume de caixa 3 m×2 m×1 m é:","why":"3×2×1=6, unidade cúbica.","law":""},{"id":330,"cat":"Informática","title":"Excel: referências absolutas e mistas","idea":"O cifrão é uma âncora para a parte que não deve se mover.","explain":"A1 muda coluna e linha; $A$1 fixa ambas; $A1 fixa coluna; A$1 fixa linha. Ao copiar fórmula, apenas as partes relativas se deslocam.","example":"=$A2*B$1 de C2 para D3 torna-se =$A3*C$1.","question":"Qual referência fixa a coluna, mas deixa a linha mudar?","why":"O $ antes da letra fixa a coluna.","law":"MS Excel 365"},{"id":333,"cat":"Informática","title":"Excel: contagem e critérios","idea":"Fórmulas são pequenos funcionários que executam instruções.","explain":"CONT.SE(intervalo;critério) conta células que cumprem uma condição; SOMASE soma valores correspondentes ao critério; SE devolve resultados diferentes dependendo do teste lógico. Dependendo do idioma/configuração, separadores e nomes mudam.","example":"=CONT.SE(A2:A10;\"Atrasado\") conta ocorrências do texto “Atrasado”.","question":"Qual função conta células que satisfazem um critério?","why":"CONT.SE faz contagem condicional.","law":"MS Excel 365"},{"id":336,"cat":"Informática","title":"Excel: filtros e formatação condicional","idea":"O filtro esconde temporariamente linhas; formatação condicional destaca automaticamente.","explain":"Classificar reordena, filtrar mostra subconjunto; formatação condicional aplica cor com base em regra. Para vencimentos, combine datas, filtros e fórmulas.","example":"Marcar em vermelho datas menores que HOJE() para itens ainda não pagos.","question":"Qual recurso destaca automaticamente vencimentos atrasados?","why":"Regras de formatação respondem aos valores da célula.","law":"MS Excel 365"},{"id":339,"cat":"Informática","title":"Word: estilos e sumário automático","idea":"Estilos são etiquetas que dizem quais partes são títulos e subtítulos.","explain":"Aplicar estilos Título 1/2 permite sumário automático consistente. Quebras de página são diferentes de vários Enter. Localizar/Substituir agiliza revisão.","example":"Se “Capítulo 1” usa Título 1, aparece no sumário após atualização.","question":"Qual recurso sustenta o sumário automático?","why":"O sumário identifica a estrutura pelos estilos.","law":"MS Word 365"},{"id":342,"cat":"Informática","title":"Segurança digital: phishing e anexos","idea":"Golpe digital costuma vestir roupa de mensagem confiável.","explain":"Verifique endereço, domínio, pedido urgente, anexos e links. Não forneça senhas a páginas suspeitas. Autenticação multifator ajuda a proteger contas, mas não substitui atenção.","example":"E-mail diz “pague agora” e imita tribunal; confira por canal oficial independente.","question":"Ao receber link suspeito, o melhor é:","why":"A conferência independente reduz risco de fraude.","law":""},{"id":345,"cat":"Informática","title":"Teams e OneDrive: permissão e versão","idea":"Compartilhar não significa liberar tudo para qualquer pessoa.","explain":"Teams oferece reuniões, canais e colaboração; OneDrive armazena arquivos em nuvem e permite controle de acesso. Diferencie visualizar de editar, sincronizar de criar cópia e histórico de versões de lixeira.","example":"Compartilhar documento somente para leitura evita edição indesejada.","question":"Qual permissão permite ler sem modificar o arquivo?","why":"Visualização não concede edição.","law":""},{"id":348,"cat":"Gerais","title":"Atualidades: diferenciar notícia e opinião","idea":"Duas manchetes podem descrever o mesmo fato de modo diferente.","explain":"Cheque data, fonte, local, personagens e contexto. Prefira fonte primária para documentos oficiais e mais de uma fonte confiável para temas controversos. Estude fatos a partir do primeiro semestre de 2026, conforme edital.","example":"Uma decisão oficial deve ser localizada no órgão responsável, e notícias ajudam a explicar impactos.","question":"Ao estudar uma notícia, o primeiro cuidado é:","why":"A prova cobra fatos e contexto, não boatos.","law":"Edital 02/2026, Anexo VIII"},{"id":351,"cat":"Gerais","title":"LBI: acessibilidade e barreiras","idea":"Acessibilidade é remover obstáculos para participação de todos.","explain":"A LBI define barreiras urbanísticas, arquitetônicas, em transportes, comunicações, atitudes e tecnologia. Estude também igualdade de oportunidades, prioridade e atendimento respeitoso nos artigos exigidos.","example":"Sistema digital sem leitor de tela pode criar barreira tecnológica para pessoa com deficiência visual.","question":"Uma página incompatível com leitor de tela pode gerar barreira:","why":"A barreira tecnológica impede acesso a ferramentas e comunicação.","law":"Lei 13.146/2015, art. 3º"},{"id":354,"cat":"Redação","title":"Redação: argumento sem exagero","idea":"Um argumento forte se sustenta com explicação, não com grito.","explain":"Faça a estrutura afirmação → por quê → consequência/ilustração. Prefira exemplos verificáveis e relações coerentes. Não invente estatísticas. Distinga tese de repertório e mantenha o recorte do tema.","example":"Tese: acesso digital facilita serviços; explicação: reduz deslocamentos; ressalva: exige acessibilidade.","question":"Qual sequência fortalece um parágrafo?","why":"A relação entre ideias gera argumento.","law":""},{"id":357,"cat":"Redação","title":"Redação: coesão e revisão","idea":"A última leitura é como revisar a mochila antes de sair.","explain":"Procure pronome sem antecedente, conectivo incoerente, repetição excessiva, frases longas e concordância. Verifique se cada parágrafo faz avançar a tese. Na Vunesp, leia os critérios específicos e evite reproduzir textos da coletânea.","example":"Primeira revisão: conteúdo; segunda: gramática; terceira: legibilidade e pontuação.","question":"Qual atitude melhora a coesão?","why":"Conectivos precisam expressar relação lógica real.","law":""},{"id":360,"cat":"Estratégia","title":"Método: resolver questões com palavras-chave","idea":"O comando da banca é a bússola da pergunta.","explain":"Sublinhe mentalmente “correta”, “incorreta”, “exceto”, “sempre” e “necessariamente”. Leia todas as alternativas antes de marcar. Em Direito, volte ao artigo; em Português, volte ao trecho.","example":"Pergunta “INCORRETA”: achar uma afirmação certa não basta.","question":"Qual palavra muda a busca para uma exceção?","why":"“Incorreta” inverte o tipo de alternativa procurada.","law":""},{"id":363,"cat":"Estratégia","title":"Plano de 12 semanas de estudo","idea":"O aprendizado se constrói como blocos de Lego, não como uma parede de uma vez.","explain":"Semana 1–4: base de Português e Direito, alternando Matemática/Informática. Semanas 5–8: aprofundar Direito, legislação interna, lógica e revisão. Semanas 9–12: questões, simulados e redação. Ajuste às dificuldades reais e ao cronograma.","example":"Estude 25 minutos, pause 5, pratique 10; registre erros que se repetem.","question":"Qual plano protege contra eliminação por bloco?","why":"Os dois blocos eliminatórios exigem mínimos próprios.","law":""}];
